(async () => {
  const pages = figma.root.children;
  const pageInfos = [];
  for (const p of pages) {
    const textNodes = p.findAll(n => n.type === 'TEXT');
    const texts = textNodes.map(t => `${t.name}: ${t.characters}`);
    pageInfos.push({
      id: p.id,
      name: p.name,
      childCount: p.children.length,
      textSample: texts.slice(0, 50)
    });
  }
  return pageInfos;
})()

(async () => {
  const page = figma.getNodeById("0:1");
  const texts = [];
  const walk = (node) => {
    if (node.type === 'TEXT') {
      texts.push({ id: node.id, name: node.name, text: node.characters });
    }
    if ('children' in node) {
      for (const child of node.children) {
        walk(child);
      }
    }
  };
  walk(page);
  return texts;
})()

(async () => {
  const pages = ["1:2", "1:3", "1:4"];
  const result = {};
  for (const pid of pages) {
    const page = figma.getNodeById(pid);
    if (!page) continue;
    const items = page.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      children: 'children' in c ? c.children.map(ch => ({ id: ch.id, name: ch.name, type: ch.type })) : []
    }));
    result[page.name] = items;
  }
  return result;
})()

(async () => {
  const compFrame = figma.getNodeById("1:24");
  const mediaFrame = figma.getNodeById("5:146");
  const foundationsPage = figma.getNodeById("1:2");

  const getSubTree = (node) => {
    return {
      id: node.id,
      name: node.name,
      type: node.type,
      children: 'children' in node ? node.children.map(getSubTree) : []
    };
  };

  return {
    foundations: foundationsPage ? getSubTree(foundationsPage) : null,
    components: compFrame ? getSubTree(compFrame) : null,
    media: mediaFrame ? getSubTree(mediaFrame) : null
  };
})()

