(async () => {
  const workspacePage = figma.getNodeById("7:2");
  await figma.setCurrentPageAsync(workspacePage);

  const screens = {};
  for (const c of workspacePage.children) {
    screens[c.name] = c;
  }

  function findChildByName(parent, name) {
    if (parent.name === name) return parent;
    if ('children' in parent) {
      for (const ch of parent.children) {
        const res = findChildByName(ch, name);
        if (res) return res;
      }
    }
    return null;
  }

  function wire(sourceNode, targetFrame) {
    if (!sourceNode || !targetFrame) return false;
    sourceNode.reactions = [
      {
        trigger: { type: "ON_CLICK" },
        action: {
          type: "NODE",
          destinationId: targetFrame.id,
          navigation: "NAVIGATE",
          transition: null
        }
      }
    ];
    return true;
  }

  const f1 = screens["01_Welcome"];
  const f2 = screens["02_Apple_ID_Sheet"];
  const f3 = screens["03_Explore"];
  const f4 = screens["04_Find_Partner"];
  const f5 = screens["05_Friend_Profile"];
  const f6 = screens["06_Short_Video"];
  const f7 = screens["07_Profile"];
  const f8 = screens["08_Menu"];

  // 1. 01_Welcome -> Sign Up -> 02_Apple_ID_Sheet
  const linkSignUp = findChildByName(f1, "Link_SignUp");
  wire(linkSignUp, f2);

  // 2. 02_Apple_ID_Sheet -> Face ID -> 03_Explore, close -> 01_Welcome
  const btnFaceId = findChildByName(f2, "Btn_Face_ID");
  const btnCloseSheet = findChildByName(f2, "Btn_Close_Sheet");
  wire(btnFaceId, f3);
  wire(btnCloseSheet, f1);

  // 3. 03_Explore -> Claire (story) -> 05_Friend_Profile, Dating tab -> 04_Find_Partner, Profile tab -> 07_Profile
  const storyClaire = findChildByName(f3, "ClaireStory");
  const tabDating3 = findChildByName(f3, "Tab_Dating");
  const tabProfile3 = findChildByName(f3, "Tab_Profile");
  wire(storyClaire, f5);
  wire(tabDating3, f4);
  wire(tabProfile3, f7);

  // 4. 04_Find_Partner -> back / Home tab -> 03_Explore, Profile tab -> 07_Profile
  const btnBack4 = findChildByName(f4, "Btn_Back_FindPartner");
  const tabHome4 = findChildByName(f4, "Tab_Home");
  const tabProfile4 = findChildByName(f4, "Tab_Profile");
  wire(btnBack4, f3);
  wire(tabHome4, f3);
  wire(tabProfile4, f7);

  // 5. 05_Friend_Profile -> back / Home tab -> 03_Explore, Short (tab) -> 06_Short_Video
  const btnBack5 = findChildByName(f5, "Btn_Back_Claire");
  const tabHome5 = findChildByName(f5, "Tab_Home");
  const tabShort5 = findChildByName(f5, "Tab_Short_Claire");
  wire(btnBack5, f3);
  wire(tabHome5, f3);
  wire(tabShort5, f6);

  // 6. 06_Short_Video -> back -> 05_Friend_Profile
  const btnBack6 = findChildByName(f6, "Btn_Back_Short");
  wire(btnBack6, f5);

  // 7. 07_Profile -> menu -> 08_Menu, Home tab -> 03_Explore
  const btnMenu7 = findChildByName(f7, "Btn_Menu_Profile");
  const tabHome7 = findChildByName(f7, "Tab_Home");
  wire(btnMenu7, f8);
  wire(tabHome7, f3);

  // 8. 08_Menu -> close / Show Profile -> 07_Profile
  const btnCloseDrawer = findChildByName(f8, "Btn_Close_Drawer");
  const linkShowProfile = findChildByName(f8, "Link_ShowProfile");
  wire(btnCloseDrawer, f7);
  wire(linkShowProfile, f7);

  const screenSummary = {};
  for (const k of Object.keys(screens)) {
    screenSummary[k] = screens[k].id;
  }

  return {
    pageId: workspacePage.id,
    screens: screenSummary
  };
})()

